   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="链尉官，你知道曙光革命吗？", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 0, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="菲谢尔忽然自顾自地说了起来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [95]={next_id=96, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="十年前爆发的政变，听说你们把皇帝驱逐，建立了双冕王厅来统治克洛瓦德。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 0, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [96]={next_id=97, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是里维莉娅大小姐这么和你说的对吧……果然那些信息是流传不出来的呢。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 0, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [97]={next_id=98, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="什么信息？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 0, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="雾灾袭来的时候，皇室没能带领国家有效地抵抗这场劫难，对皇室颇有微词的贵族们趁机逼宫，篡夺了部分权力。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 0, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但克洛瓦德的人民仍然聚集在皇室的名下，人们沉浸在丧失了亲人的悲痛中，但是仍下意识地相信着自己国家的领导者可以拯救他们。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 0, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以，贵族们干了绝对不能原谅的事情。", msg_color="", msg_size=0, talker="菲谢尔", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7187", 0, 0, 39, 202.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="绝对不能原谅的事……难道他们利用了异变体？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_207.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
